#!/usr/bin/env bash
# Pre-tool hook for Claude Code, Kiro CLI, and Cursor. Blocks posting GitHub comments,
# replies or reviews (gh via the shell tool) and Jira comments (Atlassian MCP) unless
# the body is a conventional comment (https://conventionalcomments.org/) and ends with
# the calling agent's line: "[Generated by Claude]", "[Generated by Kiro]", or
# "[Generated by Cursor]".
set -euo pipefail

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")"
event="$(jq -r '.hook_event_name // ""' <<<"$input")"
cursor_version="$(jq -r '.cursor_version // ""' <<<"$input")"

# Cursor names the event "preToolUse", the same string Kiro uses, and sends
# cursor_version on every hook. The version field is what distinguishes them.
agent=claude
if [[ -n "$cursor_version" && "$cursor_version" != "null" ]]; then
    agent=cursor
elif [[ "$event" == "preToolUse" ]]; then
    agent=kiro
fi

case "$agent" in
    cursor) PREFIX='[Generated by Cursor]' ;;
    kiro) PREFIX='[Generated by Kiro]' ;;
    *) PREFIX='[Generated by Claude]' ;;
esac

allow() {
    # Cursor permission hooks block on empty or invalid JSON. Claude and Kiro allow on exit 0.
    if [[ "$agent" == "cursor" ]]; then
        jq -n '{permission: "allow"}'
    fi
    exit 0
}

deny() {
    case "$agent" in
        kiro)
            # Kiro CLI blocks on exit 2 and returns stderr to the model.
            echo "$1" >&2
            exit 2
            ;;
        cursor)
            jq -n --arg reason "$1" \
                '{permission: "deny", user_message: $reason, agent_message: $reason}'
            exit 0
            ;;
        *)
            # Claude Code reads a JSON decision.
            jq -n --arg reason "$1" \
                '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $reason}}'
            exit 0
            ;;
    esac
}

# https://conventionalcomments.org/ — label, optional decorations, then a subject.
# The label may be bolded for Markdown: **suggestion:** or **suggestion**:
LABEL='praise|nitpick|suggestion|issue|todo|question|thought|chore|note|typo|polish|quibble'
DECORATION='( \([^)]+\))?'
CONVENTIONAL_RE="^(${LABEL})${DECORATION}: [^[:space:]].*|^\*\*(${LABEL})${DECORATION}:\*\* [^[:space:]].*|^\*\*(${LABEL})${DECORATION}\*\*: [^[:space:]].*"

# First non-empty line is the conventional comment; last non-empty line is the agent marker.
require_comment_shape() {
    local body="$1" where="$2"
    local first last
    first="$(awk 'NF { sub(/[[:space:]]+$/, ""); print; exit }' <<<"$body")"
    last="$(awk 'NF { sub(/[[:space:]]+$/, ""); line=$0 } END { print line }' <<<"$body")"
    grep -Eq "$CONVENTIONAL_RE" <<<"$first" ||
        deny "${where} must be a conventional comment (https://conventionalcomments.org/). Start with a bold label, for example '**suggestion:** short summary'."
    [[ "$last" == "$PREFIX" ]] ||
        deny "${where} must end with \"${PREFIX}\" on its own line."
}

# The body has to be visible in the command. A heredoc is the form that keeps multiline
# comments inline; a body file is not checked because its text is not in the command.
extract_heredoc_body() {
    local cmd="$1" marker
    [[ "$cmd" =~ \<\<[-]?[[:space:]]*[\'\"]?([A-Za-z_][A-Za-z0-9_]*) ]] || return 1
    marker="${BASH_REMATCH[1]}"
    awk -v marker="$marker" '
        !started && $0 ~ /<</ && index($0, marker) { started=1; next }
        started && $0 ~ "^[[:space:]]*" marker "[[:space:]]*$" { exit }
        started { print }
    ' <<<"$cmd"
}

if [[ "$tool_name" == *addCommentToJiraIssue || "$tool_name" == *addOrEditJiraIssueComment ]]; then
    require_comment_shape "$(jq -r '.tool_input.commentBody // ""' <<<"$input")" "Jira comments"
    allow
fi

command="$(jq -r '.tool_input.command // .command // ""' <<<"$input")"

posts_comment=false
if grep -qE 'gh +(pr|issue) +comment\b' <<<"$command"; then
    posts_comment=true
elif grep -qE 'gh +pr +review\b' <<<"$command" && grep -qE '(^| )(-b|--body|-F|--body-file)( |=)' <<<"$command"; then
    posts_comment=true
elif grep -qE 'gh +api\b' <<<"$command" && grep -qE '/(comments|replies|reviews)\b' <<<"$command" &&
    grep -qE '(^| )(-f|-F|--field|--raw-field|--input|-X|--method)( |=)' <<<"$command" &&
    ! grep -qiE '(-X|--method)( |=)GET\b' <<<"$command"; then
    posts_comment=true
fi

if [[ "$posts_comment" == true ]]; then
    body="$(extract_heredoc_body "$command")" ||
        deny "GitHub comments must be passed inline in a heredoc, not a body file, so the format can be checked."
    require_comment_shape "$body" "GitHub comments"
fi

allow
